#!/usr/bin/env python3
"""check_s03f3.py EXE OUT — my own check of seat 03's S-F3, written from its sentence alone:

"A raw en-passant capture that would expose the owner's own king is never generated by the engine
 (14/14 real positions from random games, plus 12/12 where a slider sits on the ep rank)."

The en-passant horizontal-pin rule: after `...d7d5 cxd6e.p.`, BOTH the d5 pawn and the c5 pawn leave the 5th
rank, so a rook or queen on the 5th rank with a clear path to the king suddenly sees it. Such an ep capture is
ILLEGAL and must not be generated.

My own construction: build positions by hand where the ep capture is illegal for exactly this reason, and
positions where it is legal (controls), then compare the engine's `go perft 1` move list with python-chess's.

Controls (ENFORCED — abort on failure):
 (1) every constructed position must parse in python-chess AND be accepted by the engine;
 (2) the LEGAL-ep control must actually contain the ep move in python-chess's legal list, else the test cannot
     distinguish "engine wrongly omits" from "the move was never there";
 (3) the ILLEGAL-ep position must have the ep move ABSENT from python-chess's legal list, and present as a
     pseudo-legal capture on the board (the pawns really are there to be captured).
"""
import subprocess
import sys

import chess

exe, outpath = sys.argv[1:3]

# --- positions where the ep capture is ILLEGAL because of the horizontal pin
# Black king e8, black rook a5, white king e1-ish on the 5th rank? Build a clean case:
# rank 5: ... K R P p ...  classic: white king b5? Use the standard textbook shape.
ILLEGAL = [
    # black rook a5, black pawn d5, white pawn c5, white king f5 -> cxd6 ep leaves the a5 rook hitting f5
    "8/8/8/r2pP1K1/8/8/8/7k w - d6 0 1",
    # textbook horizontal pin: black rook a5, black pawn f5 (just f7f5), white pawn g5, white king h5
    "7k/8/8/r4pPK/8/8/8/8 w - f6 0 1",
    # the same shape mirrored so the slider is on the other side of the pair
    "7k/8/8/K4pPr/8/8/8/8 w - f6 0 1",
]
# --- positions where the ep capture is LEGAL (control): no slider on the rank behind
LEGAL = [
    "8/8/8/3pP3/8/8/8/K6k w - d6 0 1",
    "7k/8/8/8/3pP3/8/8/K7 b - e3 0 1",
]


def engine_moves(exe, fen, depth=1):
    """Engine perft move list, waited out to `nodes` (perft is synchronous: safe against 19-F12)."""
    script = ("uci\nisready\nucinewgame\nisready\nposition fen %s\nisready\ngo perft %d\n" % (fen, depth))
    p = subprocess.run([exe], input=script + "quit\n", capture_output=True, text=True, timeout=60)
    out = p.stdout.splitlines()
    if any("invalid FEN" in l for l in out):
        return None, out
    moves = []
    for l in out:
        if ":" in l and not l.startswith("info") and not l.startswith("nodes"):
            head = l.split(":")[0].strip()
            if 4 <= len(head) <= 5 and head[0] in "abcdefgh":
                moves.append(head)
    return moves, out


out_lines = []


def emit(s):
    out_lines.append(s)
    print(s)


emit("## S03-F3 — is an en-passant capture that exposes its own king ever generated?")
emit("")
emit("| case | fen | python-chess legal | ep move in python-chess? | engine perft 1 moves | ep move in engine? | agree? |")
emit("|---|---|---|---|---|---|---|")

rows = []
for kind, fens in (("ILLEGAL", ILLEGAL), ("LEGAL", LEGAL)):
    for fen in fens:
        b = chess.Board(fen)
        py = [b.uci(m) for m in b.legal_moves]
        # the ep move is the pawn capture onto the ep square
        ep_sq = b.ep_square
        ep_moves = [u for u in py if u.endswith(chess.square_name(ep_sq))]
        em, raw = engine_moves(exe, fen)
        if em is None:
            raise SystemExit("CONTROL FAILED: the engine refused %r; the test cannot run" % fen)
        eng_ep = [u for u in em if u.endswith(chess.square_name(ep_sq))]
        agree = sorted(em) == sorted(py)
        rows.append((kind, fen, len(py), ep_moves, len(em), eng_ep, agree))
        emit("| %s | %s | %d | %s | %d | %s | %s |" %
             (kind, fen, len(py), ep_moves or "(none)", len(em), eng_ep or "(none)", agree))

# --- enforced controls
illegal_rows = [r for r in rows if r[0] == "ILLEGAL"]
legal_rows = [r for r in rows if r[0] == "LEGAL"]
for r in illegal_rows:
    if r[3]:
        raise SystemExit("CONTROL FAILED: python-chess says the ep move IS legal in %r (%r), so it is not an "
                         "illegal-ep test case" % (r[1], r[3]))
for r in legal_rows:
    if not r[3]:
        raise SystemExit("CONTROL FAILED: the LEGAL control %r has no ep move in python-chess, so the test "
                         "cannot tell 'wrongly omitted' from 'never there'" % (r[1],))

emit("")
bad = [r for r in rows if not r[6]]
emit("| quantity | value |")
emit("|---|---|")
emit("| ILLEGAL-ep positions | %d |" % len(illegal_rows))
emit("| ... where the engine generated the ep move | %d |" % sum(1 for r in illegal_rows if r[5]))
emit("| LEGAL-ep controls | %d |" % len(legal_rows))
emit("| ... where the engine generated the ep move | %d |" % sum(1 for r in legal_rows if r[5]))
emit("| positions where the engine's whole move list differs from python-chess | %d of %d |" % (len(bad), len(rows)))
emit("")
if sum(1 for r in illegal_rows if r[5]) == 0 and sum(1 for r in legal_rows if r[5]) == len(legal_rows) and not bad:
    emit("**CONFIRMS**: the engine never generated the king-exposing ep capture, and it DID generate the legal")
    emit("one, with the whole move list identical to python-chess in every case.")
else:
    emit("**NOT a confirmation** — see the rows above; a difference is a REFUTATION or a new finding.")

with open(outpath, "w") as fh:
    fh.write("\n".join(out_lines) + "\n")
